import unittest
from program import run

class T(unittest.TestCase):
    def test_case_00(self):
        self.assertEqual(run(['3', '1', '2']), {'n': 3, 'min': 3, 'span': 0, 'flags': ['min', 'n']})
    def test_case_01(self):
        self.assertEqual(run(['10', '0', '7', 'x']), {'n': 4, 'min': 3, 'span': 3, 'flags': ['min', 'n', 'span']})
    def test_case_02(self):
        self.assertEqual(run([' 5 ', '-2', '8']), {'n': 3, 'min': 3, 'span': 3, 'flags': ['min', 'n', 'span']})
    def test_case_03(self):
        self.assertEqual(run(['4:2', '9:1', 'bad']), {'n': 3, 'min': 9, 'span': 0, 'flags': ['min', 'n']})
    def test_case_04(self):
        self.assertEqual(run(['12', '12', '1']), {'n': 3, 'min': 3, 'span': 3, 'flags': ['min', 'n', 'span']})
    def test_case_05(self):
        self.assertEqual(run(['0']), {'n': 1, 'min': 3, 'span': 0, 'flags': ['min', 'n']})
    def test_case_06(self):
        self.assertEqual(run(['6', '6', '6', '6']), {'n': 4, 'min': 3, 'span': 0, 'flags': ['min', 'n']})
    def test_case_07(self):
        self.assertEqual(run(['2', 'hello', '40']), {'n': 3, 'min': 3, 'span': 12, 'flags': ['min', 'n', 'span']})

if __name__ == '__main__':
    unittest.main()
